from version_compare import compare_versions


def newest_compatible(versions: list[str], minimum: str) -> str | None:
    """Return the highest version in `versions` that is >= `minimum`, or None."""
    best = None
    for version in versions:
        if compare_versions(version, minimum) >= 0:
            if best is None or compare_versions(version, best) > 0:
                best = version
    return best

"""Run coroutines concurrently from synchronous code with a deadline.

This helper is intended for ordinary synchronous callers (for example CLI code)
where no asyncio event loop is already running.
"""
import asyncio
from typing import Any, List


async def _run_with_deadline_async(coros, seconds):
    tasks = [asyncio.create_task(coro) for coro in coros]
    try:
        done, pending = await asyncio.wait(
            tasks,
            timeout=seconds,
            return_when=asyncio.ALL_COMPLETED,
        )

        # Preserve input order; return None for unfinished coroutines.
        results = []
        for task in tasks:
            if task in done:
                results.append(task.result())
            else:
                results.append(None)

        # Cancel anything that did not finish in time and let cancellation settle.
        if pending:
            for task in pending:
                task.cancel()
            await asyncio.gather(*pending, return_exceptions=True)

        return results
    except BaseException:
        for task in tasks:
            if not task.done():
                task.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        raise


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently and return results in input order.

    Any coroutine that does not finish within `seconds` is cancelled and its
    result position is set to None.
    """
    return asyncio.run(_run_with_deadline_async(list(coros), seconds))

from web_utils import parse_content_type, image_type


def describe_upload(content_type: str, data: bytes) -> dict:
    """
    Describe an uploaded payload.

    Returns:
        {
            "mime": lower-cased media type without parameters,
            "charset": lower-cased charset parameter or None,
            "image": "png", "jpeg", or "gif" if detected from signature bytes, else None,
        }
    """
    mime, params = parse_content_type(content_type)
    charset = params.get("charset")
    if charset is not None:
        charset = charset.lower()

    img = image_type(data)
    if img not in {"png", "jpeg", "gif"}:
        img = None

    return {"mime": mime, "charset": charset, "image": img}

"""Run coroutines from synchronous code with a deadline.

This module provides `run_with_deadline`, which executes a collection of
coroutines concurrently from ordinary synchronous code, returning results in
input order and `None` for any coroutine that does not finish before the
deadline.
"""

from __future__ import annotations

import asyncio
from typing import Any, List


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently and return their results in input order.

    Any coroutine that is still pending after `seconds` is cancelled and its
    result position is set to None.

    This function creates and closes its own event loop so it can be called
    repeatedly in the same process.
    """
    async def _main():
        tasks = [asyncio.create_task(coro) for coro in coros]
        try:
            done, pending = await asyncio.wait(
                tasks, timeout=seconds, return_when=asyncio.ALL_COMPLETED
            )
            results = [None] * len(tasks)

            for idx, task in enumerate(tasks):
                if task in done:
                    try:
                        results[idx] = task.result()
                    except Exception:
                        # Propagate exceptions from completed coroutines.
                        # Cancel any other pending tasks before re-raising.
                        for p in pending:
                            p.cancel()
                        if pending:
                            await asyncio.gather(*pending, return_exceptions=True)
                        raise

            if pending:
                for task in pending:
                    task.cancel()
                await asyncio.gather(*pending, return_exceptions=True)

            return results
        finally:
            # Ensure no task is left pending if anything unexpected happens.
            for task in tasks:
                if not task.done():
                    task.cancel()
            if tasks:
                await asyncio.gather(*tasks, return_exceptions=True)

    try:
        return asyncio.run(_main())
    except RuntimeError as exc:
        # Keep the function safe for synchronous callers; if an event loop is
        # already running, this would violate the intended usage.
        raise PermissionError(
            "run_with_deadline must be called from ordinary synchronous code"
        ) from exc

"""Call asyncio code from synchronous code (CLI commands, WSGI views, scripts)."""
import asyncio


def run_sync(coro):
    """Run a coroutine to completion from synchronous code and return its result."""
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        loop = None
    if loop is not None:
        raise RuntimeError("run_sync() cannot be called from a running event loop")
    return asyncio.run(coro)


def run_all(coros, limit=None):
    """Run coroutines concurrently (at most `limit` at a time) and return their results in order."""
    async def _main():
        sem = asyncio.Semaphore(limit) if limit else None

        async def _one(c):
            if sem is None:
                return await c
            async with sem:
                return await c

        return await asyncio.gather(*(_one(c) for c in coros))

    return run_sync(_main())


async def with_timeout(coro, seconds, default=None):
    """Await `coro`; return `default` if it does not finish within `seconds`."""
    try:
        return await asyncio.wait_for(coro, seconds)
    except asyncio.TimeoutError:
        return default


async def retry_async(func, attempts=3, delay=0.0, exceptions=(Exception,)):
    """Await func() until it succeeds, at most `attempts` times; re-raise the last error."""
    for i in range(attempts):
        try:
            return await func()
        except exceptions:
            if i == attempts - 1:
                raise
            await asyncio.sleep(delay)


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently with a deadline.

    Returns results in input order. Any coroutine still pending after `seconds`
    is cancelled and represented as ``None`` in the returned list.
    """
    async def _main():
        tasks = [asyncio.create_task(coro) for coro in coros]
        try:
            done, pending = await asyncio.wait(tasks, timeout=seconds)

            for task in pending:
                task.cancel()

            if pending:
                await asyncio.gather(*pending, return_exceptions=True)

            results = [None] * len(tasks)
            for idx, task in enumerate(tasks):
                if task in done:
                    results[idx] = await task
            return results
        except BaseException:
            for task in tasks:
                task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)
            raise

    return run_sync(_main())

from web_utils import content_charset, parse_content_type, image_type


def describe_upload(content_type: str, data: bytes) -> dict:
    """
    Describe an upload body from its Content-Type header and leading bytes.

    Returns:
        {
            "mime": <lower-cased media type without parameters>,
            "charset": <lower-cased charset parameter or None>,
            "image": <"png", "jpeg", "gif" or None>,
        }
    """
    mime, params = parse_content_type(content_type)
    charset = params.get("charset")
    if charset is not None:
        charset = charset.lower()

    image = image_type(data)
    if image not in {"png", "jpeg", "gif"}:
        image = None

    return {
        "mime": mime,
        "charset": charset,
        "image": image,
    }
